-- Generated by packages/db/tests/run-db-baseline-replay.mjs --write-built from the database built from repository files.
-- Do not edit by hand; see packages/db/functions/README.md.

-- pay_waffo_atomic_refund_termination_clawback(uuid,uuid,text,text,text,text,text,boolean,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_waffo_atomic_refund_termination_clawback(p_source_order_id uuid, p_user_id uuid, p_subscription_id text, p_event_id text, p_period_key text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_reason text DEFAULT 'stripe_refund'::text, p_termination_only boolean DEFAULT false, p_refund_id text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(transaction_id uuid, balance_after integer, clawback_amount integer, applied_clawback_amount integer, shortfall_amount integer, already_applied boolean, termination_written boolean, already_terminated boolean, grant_reversed boolean, already_reversed boolean, credits_granted integer, consumed_amount integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_source_order public.payment_orders;
  v_source_subscription public.user_subscriptions;
  v_now TIMESTAMPTZ := COALESCE(p_now, now());
  v_full_mode BOOLEAN;
  v_termination_written BOOLEAN := FALSE;
  v_balance_before INTEGER;
  v_mirror_id UUID;
  v_grant_id UUID;
  v_grant_status TEXT;
  v_grant_granted INTEGER;
  v_grant_consumed INTEGER;
  v_clawback INTEGER := 0;
  v_applied INTEGER := 0;
  v_shortfall INTEGER := 0;
  v_transaction_id UUID;
  v_existing_transaction RECORD;
  v_existing_termination_at TIMESTAMPTZ;
BEGIN

  -- Keep the original profile -> subscription -> grant lock order. The order is
  -- locked after the profile; every nested call verifies the same source again.
  PERFORM 1 FROM public.profiles WHERE id=p_user_id FOR UPDATE;
  SELECT * INTO v_source_order FROM public.payment_orders
    WHERE id=p_source_order_id AND user_id=p_user_id AND payment_channel='stripe' FOR SHARE;
  IF NOT FOUND OR v_source_order.subscription_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WAFFO_REFUND_SOURCE_MISMATCH' USING ERRCODE='23514';
  END IF;
  SELECT * INTO v_source_subscription FROM public.user_subscriptions
    WHERE id=v_source_order.subscription_id AND user_id=p_user_id
      AND payment_channel=v_source_order.payment_channel
      AND merchant_namespace=v_source_order.merchant_namespace AND payment_mode=v_source_order.payment_mode FOR UPDATE;
  IF NOT FOUND OR (v_source_subscription.stripe_subscription_id IS NOT NULL
    AND v_source_subscription.stripe_subscription_id IS DISTINCT FROM p_subscription_id)
    OR NOT EXISTS(SELECT 1 FROM public.payment_provider_refs r
    WHERE r.subscription_id=v_source_subscription.id AND r.channel='stripe' AND r.object_type='subscription'
      AND r.merchant_namespace=v_source_order.merchant_namespace AND r.mode=v_source_order.payment_mode
      AND r.external_id=p_subscription_id) THEN
    RAISE EXCEPTION 'PAY_WAFFO_REFUND_SOURCE_MISMATCH' USING ERRCODE='23514';
  END IF;
  IF btrim(COALESCE(p_subscription_id, '')) = '' THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_SUBSCRIPTION_ID_REQUIRED';
  END IF;

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_USER_REQUIRED';
  END IF;

  -- R2/R8: every mode binds the profile and the subscription mirror before
  -- any termination or grant mutation; the profile lock remains first.
  SELECT credits INTO v_balance_before
  FROM profiles
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_PROFILE_MISSING: %', p_user_id;
  END IF;

  v_full_mode := (p_termination_only IS NOT TRUE) AND (btrim(COALESCE(p_period_key, '')) <> '');

  IF v_full_mode THEN
    IF btrim(COALESCE(p_idempotency_key, '')) = '' THEN
      RAISE EXCEPTION 'REFUND_CLAWBACK_CANONICAL_IDEMPOTENCY_KEY_REQUIRED';
    END IF;

    -- R1: 持锁后复查 canonical (event_id + subscription_id + period_key) 幂等键;
    --     唯一索引 idx_credit_transactions_user_idempotency_key 是最终硬屏障
    SELECT ct.id,
           ct.balance_before,
           ct.balance_after,
           COALESCE(NULLIF(ct.metadata->>'requiredClawbackAmount', '')::INTEGER, ABS(ct.amount))
             AS required_amount,
           COALESCE(NULLIF(ct.metadata->>'appliedClawbackAmount', '')::INTEGER, ABS(ct.amount))
             AS applied_amount,
           COALESCE(NULLIF(ct.metadata->>'shortfallAmount', '')::INTEGER, 0)
             AS shortfall_amount
    INTO v_existing_transaction
    FROM credit_transactions AS ct
    WHERE ct.user_id = p_user_id
      AND ct.idempotency_key = p_idempotency_key
    LIMIT 1;

    IF FOUND THEN
      RETURN QUERY SELECT
        v_existing_transaction.id,
        v_existing_transaction.balance_after::integer,
        v_existing_transaction.required_amount::integer,
        v_existing_transaction.applied_amount::integer,
        v_existing_transaction.shortfall_amount::integer,
        TRUE,
        FALSE,
        FALSE,
        TRUE,
        FALSE,
        NULL::INTEGER,
        NULL::INTEGER;
      RETURN;
    END IF;
  END IF;

  -- R5: 先写 termination (首个成功事件确立); mirror 缺失即失败关闭,
  --     不得继续 grant reversal / clawback
  -- R8: lock the mirror for the same owner/subscription before writing its
  -- termination marker; a mismatched owner's mirror is not a valid binding.
  SELECT id, credit_release_terminated_at
  INTO v_mirror_id, v_existing_termination_at
  FROM user_subscriptions
  WHERE id = v_source_subscription.id
    AND user_id = p_user_id
  ORDER BY created_at ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_SUBSCRIPTION_MIRROR_MISSING: %', p_subscription_id;
  END IF;

  IF v_existing_termination_at IS NULL THEN
    UPDATE user_subscriptions
    SET credit_release_terminated_at = v_now,
        credit_release_terminated_reason = COALESCE(NULLIF(btrim(p_reason), ''), 'stripe_refund'),
        credit_release_terminated_event_id = p_event_id,
        credit_release_terminated_period_key = p_period_key,
        updated_at = v_now
    WHERE id = v_mirror_id
      AND credit_release_terminated_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'REFUND_CLAWBACK_SUBSCRIPTION_TERMINATION_WRITE_MISS: %', p_subscription_id;
    END IF;

    v_termination_written := TRUE;
  END IF;

  -- REVIEW_REQUIRED / termination-only: 只停止未来释放, 不猜测扣款
  IF NOT v_full_mode THEN
    RETURN QUERY SELECT
      NULL::UUID,
      NULL::INTEGER,
      0,
      0,
      0,
      FALSE,
      v_termination_written,
      (NOT v_termination_written),
      FALSE,
      FALSE,
      NULL::INTEGER,
      NULL::INTEGER;
    RETURN;
  END IF;

  -- 后续事件不得重复扣款 (首个成功事件已确立 termination 并完成其扣款)
  IF NOT v_termination_written THEN
    RETURN QUERY SELECT
      NULL::UUID,
      v_balance_before,
      0,
      0,
      0,
      FALSE,
      FALSE,
      TRUE,
      FALSE,
      FALSE,
      NULL::INTEGER,
      NULL::INTEGER;
    RETURN;
  END IF;

  -- R8: 持锁 (profile 已锁) 定位周期 grant; 缺失/状态异常即失败关闭
  SELECT g.id, g.status, g.credits_granted, g.consumed_amount
  INTO v_grant_id, v_grant_status, v_grant_granted, v_grant_consumed
  FROM subscription_credit_grants AS g
  JOIN user_subscriptions AS us
    ON us.id = v_mirror_id
   AND us.id = g.subscription_id
   AND us.user_id = p_user_id
  WHERE g.user_id = p_user_id
    AND g.subscription_id = v_source_subscription.id
    AND g.grant_period_key = p_period_key
  ORDER BY g.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_GRANT_MISSING: % / %', p_subscription_id, p_period_key;
  END IF;

  IF v_grant_status NOT IN ('granted', 'reversed') THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_GRANT_UNEXPECTED_STATUS: % (%)', p_period_key, v_grant_status;
  END IF;

  IF v_grant_status = 'reversed' THEN
    -- 该周期已被先前尝试反转: 不重复扣
    RETURN QUERY SELECT
      NULL::UUID,
      v_balance_before,
      0,
      0,
      0,
      FALSE,
      FALSE,
      FALSE,
      FALSE,
      TRUE,
      v_grant_granted,
      v_grant_consumed;
    RETURN;
  END IF;

  UPDATE subscription_credit_grants
  SET status = 'reversed',
      updated_at = v_now,
      metadata = COALESCE(metadata, '{}'::JSONB) || jsonb_build_object(
        'reversal',
        jsonb_build_object(
          'refundId', p_refund_id,
          'eventId', p_event_id,
          'subscriptionId', p_subscription_id, 'internalSubscriptionId', v_source_subscription.id, 'sourceOrderId', p_source_order_id,
          'periodKey', p_period_key,
          'idempotencyKey', p_idempotency_key,
          'reversedAt', v_now,
          'source', 'subscription_refund'
        )
      )
  WHERE id = v_grant_id
    AND status = 'granted';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'REFUND_CLAWBACK_GRANT_REVERSAL_RACE: %', p_period_key;
  END IF;

  -- clawback = granted - consumed (持锁值); 以当前余额封顶, 绝不为负
  v_clawback := GREATEST(v_grant_granted - v_grant_consumed, 0);
  v_applied := LEAST(v_clawback, v_balance_before);
  v_shortfall := v_clawback - v_applied;

  IF v_applied > 0 THEN
    UPDATE profiles
    SET credits = v_balance_before - v_applied
    WHERE id = p_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'REFUND_CLAWBACK_PROFILE_UPDATE_MISS: %', p_user_id;
    END IF;

  END IF;

  -- R1/B: persist the complete first-event result even when applied is zero.
  -- A zero-amount refund_clawback row changes no balance and does not count as
  -- spend, but its unique canonical key is the durable replay barrier.
  INSERT INTO credit_transactions (
    user_id,
    amount,
    type,
    ledger_type,
    reason_code,
    counts_as_spend,
    source_type,
    source_id,
    source_refund_id,
    grant_period_key,
    description,
    idempotency_key,
    balance_before,
    balance_after,
    metadata
  ) VALUES (
    p_user_id,
    -v_applied,
    'deduction',
    'refund_clawback',
    'refund_clawback',
    FALSE,
    'stripe_refund',
    p_refund_id,
    p_refund_id,
    p_period_key,
    format(
      'Stripe subscription refund credit clawback [subscription:%s refund:%s grants:1]',
      p_subscription_id,
      COALESCE(NULLIF(btrim(COALESCE(p_refund_id, '')), ''), 'unknown')
    ),
    p_idempotency_key,
    v_balance_before,
    v_balance_before - v_applied,
    jsonb_build_object(
      'canonicalResult', 'refund_clawback',
      'eventId', p_event_id,
      'subscriptionId', p_subscription_id, 'internalSubscriptionId', v_source_subscription.id, 'sourceOrderId', p_source_order_id,
      'periodKey', p_period_key,
      'refundId', p_refund_id,
      'idempotencyKey', p_idempotency_key,
      'requiredClawbackAmount', v_clawback,
      'appliedClawbackAmount', v_applied,
      'shortfallAmount', v_shortfall,
      'reviewRequired', (v_shortfall > 0),
      'reversedGrantCount', 1
    )
  )
  RETURNING id INTO v_transaction_id;

  RETURN QUERY SELECT
    v_transaction_id,
    v_balance_before - v_applied,
    v_clawback,
    v_applied,
    v_shortfall,
    FALSE,
    TRUE,
    FALSE,
    TRUE,
    FALSE,
    v_grant_granted,
    v_grant_consumed;
END;
$function$;
